"""Reference tables from PDF B.6.2 and B.6.4-B.6.5 that are not unit records: printed rows kept verbatim (wrapped lines joined) with
their printed tier word and source keys, effective tier under CLAUDE.md Law cl.4.  Nothing here is paraphrased or extended; the
structured fields the manifest draws from (items, defaults, units) live in kit_items / kit_src_*.py."""
from kit_sources import eff_tier

REFERENCE = {}


def R(group, rid, item, text, printed, keys=(), note=None, **kw):
    keys = list(keys)
    d = {"id": rid, "item": item, "printed": text, "tier_printed": printed, "source_keys": keys}
    if printed in ("documented", "inferred", "plausible-procedural") or printed.startswith("documented"):
        t, weak, why = eff_tier("documented" if printed.startswith("documented") else printed, keys, printed_weak=("weak" in printed))
        d.update({"tier": t, "weak_source": weak})
        if why:
            d["tier_note"] = why
    elif printed.startswith("weak"):
        t, weak, why = eff_tier("inferred", keys, True)
        d.update({"tier": t, "weak_source": True, "tier_note": "printed 'weak forum': tier inferred, weak"})
    else:
        d.update({"tier": "gap", "weak_source": None})
    if note:
        d["note"] = note
    d.update(kw)
    REFERENCE.setdefault(group, []).append(d)
    return d


